-- Ready Stock: whole-model summaries, exact GB/grade breakdown and bounded phones.
DO $ready_models_install$ BEGIN EXECUTE $ddl$
do $$begin if public.get_accounts_read_speed_version()is distinct from '20261113-accounts-read-speed-1'then raise exception 'Verify the current stock/read-speed update first.';end if;if public.get_ready_stock_color_groups_version()is distinct from '20261112-ready-stock-color-1'then raise exception 'Verify Ready Stock Color Groups first.';end if;if to_regprocedure('public.get_ready_stock_models_version()')is not null then if public.get_ready_stock_models_version()is distinct from '20261113-ready-stock-models-1'then raise exception 'Existing Ready Stock model integrity needs review.';end if;end if;end;$$;
create or replace function greenloop_private.rsm_read(p_mode text,p_date date,p_groups jsonb,p_from date,p_to date,p_view text,p_model text,p_cell jsonb,p_offset integer,p_limit integer,p_expected_snapshot text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare day_value date:=coalesce(p_date,(now()at time zone 'Asia/Dubai')::date);names boolean;result jsonb;payload jsonb;token text;
begin
 perform greenloop_private.require_office_network();perform greenloop_private.pf_cap('ready_stock','view');
 if greenloop_private.damage_tv_only(auth.uid())or not public.has_role(array['super_admin','owner','manager','production','final_qc','shop_staff']::public.app_role_key[])then raise exception 'Ready Stock view permission is required.'using errcode='42501';end if;
 if p_mode is null or p_mode not in('current','ready','export')then raise exception 'Choose a stock report.'using errcode='22023';end if;
 if p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 then raise exception 'Choose a valid 50-row page.'using errcode='22023';end if;
 if(p_from is null)<>(p_to is null)or(p_from is not null and p_from>p_to)then raise exception 'Choose a valid date range.'using errcode='22023';end if;
 if p_mode<>'current'and(p_groups is not null or p_from is not null)then raise exception 'Daily reports use their selected day.'using errcode='22023';end if;
 if p_from is not null or(p_mode<>'current'and day_value<>(now()at time zone 'Asia/Dubai')::date)then perform greenloop_private.pf_cap('ready_stock','search');end if;
 if p_mode<>'current'and day_value>(now()at time zone 'Asia/Dubai')::date then raise exception 'Choose today or an earlier date.'using errcode='22023';end if;
 if p_groups is not null then
  if jsonb_typeof(p_groups)<>'array'or jsonb_array_length(p_groups)not between 1 and 10000 then raise exception 'Choose valid stock groups.'using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_groups)g where jsonb_typeof(g)<>'object'or jsonb_typeof(g->'m')is distinct from 'string'or jsonb_typeof(g->'g')is distinct from 'string'or length(g->>'m')not between 1 and 1000 or length(g->>'g')not between 1 and 200)then raise exception 'Choose valid stock groups.'using errcode='22023';end if;
 end if;

 if p_view is null or p_view not in('models','breakdown','phones')or(p_view='models'and(p_model is not null or p_cell is not null))or(p_view<>'models'and(nullif(btrim(p_model),'')is null or length(p_model)>1000))or(p_view<>'phones'and p_cell is not null)then raise exception 'Choose a model summary or exact model.'using errcode='22023';end if;
 if p_view='phones'then
  if jsonb_typeof(p_cell)is distinct from 'object'or not(p_cell?'storage_gb'and p_cell?'grade_key')or(select count(*)from jsonb_object_keys(p_cell))<>2 or jsonb_typeof(p_cell->'grade_key')is distinct from 'string'or length(p_cell->>'grade_key')not between 1 and 200 or jsonb_typeof(p_cell->'storage_gb')not in('number','null')then raise exception 'Choose one GB and grade quantity.'using errcode='22023';end if;
  if p_cell->>'storage_gb'is not null then if(p_cell->>'storage_gb')!~'^[0-9]{1,6}$'then raise exception 'Choose valid GB.'using errcode='22023';end if;end if;
 end if;
 if(p_expected_snapshot is not null and p_expected_snapshot!~'^[a-f0-9]{32}$')or(p_view<>'models'and p_expected_snapshot is null)then raise exception 'Refresh the model summary before opening details.'using errcode='22023';end if;
 names:=coalesce(public.get_my_partner_name_access(),false);
 with facts as materialized(select *from greenloop_private.rsg_facts(p_mode,day_value,p_groups,p_from,p_to)),receipts as materialized(select *from greenloop_private.sc_receipts()where parent_batch_id is null),base as materialized(
  select f.*,d.imei_1 imei,coalesce(nullif(regexp_replace(btrim(d.model),'^iPhone\s+','','i'),''),'Unknown model')model,lower(regexp_replace(coalesce(nullif(regexp_replace(btrim(d.model),'^iPhone\s+','','i'),''),'Unknown model'),'\s+',' ','g'))model_key,d.storage_gb,d.color,
   lower(regexp_replace(btrim(coalesce(nullif(btrim(f.final_grade),''),'Unspecified')),'\s+',' ','g'))grade_key,coalesce(rb.batch_id,b.id)batch_id,coalesce(rb.batch_number,b.batch_number)batch_number,coalesce(rb.invoice_number,b.invoice_number)invoice_number,coalesce(rb.received_quantity,b.planned_quantity)planned_quantity,sp.supplier_code,case when names then sp.company_name end supplier_name
  from facts f join public.devices d on d.id=f.device_id join public.jobs j on j.id=f.job_id left join public.receiving_batches b on b.id=j.receiving_batch_id left join receipts rb on j.receiving_batch_id=any(rb.descendant_ids)left join public.suppliers sp on sp.id=coalesce(rb.supplier_id,j.supplier_id,b.supplier_id)
 )select coalesce(jsonb_agg(to_jsonb(b)order by b.model_key,b.storage_gb,b.grade_key,b.imei,b.job_id),'[]')into payload from base b;
 token:=md5(jsonb_build_array(p_mode,case when p_mode<>'current'then day_value end,p_groups,p_from,p_to,payload)::text);
 if p_expected_snapshot is not null and p_expected_snapshot<>token then raise exception 'Ready Stock changed. Refresh Model Summary before opening details.'using errcode='40001';end if;
 with base as materialized(select value r from jsonb_array_elements(payload)),models as materialized(select r->>'model_key'key,min(r->>'model')model,count(*)quantity from base group by r->>'model_key'),selected as materialized(select r from base where r->>'model_key'=p_model),grades as materialized(
  select r->>'grade_key'key,case when r->>'grade_key'in('a','b','d','ba','bb','rma')then upper(r->>'grade_key')else min(r->>'final_grade')end label,count(*)quantity from selected group by r->>'grade_key'
 ),buckets as materialized(select nullif(r->>'storage_gb','')::integer storage_gb,count(*)quantity from selected group by nullif(r->>'storage_gb','')::integer),cells as materialized(select nullif(r->>'storage_gb','')::integer storage_gb,r->>'grade_key'grade_key,count(*)quantity from selected group by nullif(r->>'storage_gb','')::integer,r->>'grade_key'),phones as materialized(select r from selected where nullif(r->>'storage_gb','')::integer is not distinct from nullif(p_cell->>'storage_gb','')::integer and r->>'grade_key'=p_cell->>'grade_key')
 select jsonb_build_object('version','20261113-ready-stock-models-1','mode',p_mode,'date',case when p_mode<>'current'then day_value end,'view',p_view,'offset',p_offset,'limit',p_limit,'snapshot',token,'model_key',p_model,'model',(select model from models where key=p_model),'cell',p_cell,'names_allowed',names,'phone_total',jsonb_array_length(payload),'model_total',(select count(*)from selected),'total',case p_view when 'models'then(select count(*)from models)when 'breakdown'then(select count(*)from buckets)else(select count(*)from phones)end,
 'grades',case when p_view='models'then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(g)order by case key when 'a'then 1 when 'b'then 2 when 'd'then 3 when 'ba'then 4 when 'bb'then 5 when 'rma'then 6 else 7 end,key)from grades g),'[]')end,
 'rows',case p_view when 'models'then coalesce((select jsonb_agg(to_jsonb(m)order by lower(model),key)from(select *from models order by lower(model),key offset p_offset limit p_limit)m),'[]')when 'breakdown'then coalesce((select jsonb_agg(to_jsonb(b)||jsonb_build_object('grades',(select coalesce(jsonb_agg(to_jsonb(c)order by grade_key),'[]')from cells c where c.storage_gb is not distinct from b.storage_gb))order by b.storage_gb nulls last)from(select *from buckets order by storage_gb nulls last offset p_offset limit p_limit)b),'[]')else coalesce((select jsonb_agg(r order by r->>'imei',r->>'job_id')from(select r from phones order by r->>'imei',r->>'job_id'offset p_offset limit p_limit)p),'[]')end)into result;
 return result;
end;$$;
revoke all on function greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)from public,anon,authenticated;
create or replace function public.get_ready_stock_models_v1(p_mode text,p_date date default null,p_groups jsonb default null,p_date_from date default null,p_date_to date default null,p_view text default 'models',p_model text default null,p_cell jsonb default null,p_offset integer default 0,p_limit integer default 50,p_expected_snapshot text default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$begin
 -- greenloop-office-wrapper-196
 perform greenloop_private.require_office_network();return greenloop_private.rsm_read(p_mode,p_date,p_groups,p_date_from,p_date_to,p_view,p_model,p_cell,p_offset,p_limit,p_expected_snapshot);end;$$;
revoke all on function public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)from public,anon;grant execute on function public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)to authenticated;
insert into greenloop_private.office_routines values('public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)',md5(pg_get_functiondef('greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)'::regprocedure)),md5(pg_get_functiondef('public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)'::regprocedure)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
insert into greenloop_private.capability_rpc_rules values('get_ready_stock_models_v1','{"page":"ready_stock","capability":"view","read":true}'),('get_ready_stock_models_version','{"read":true}')on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
create table if not exists greenloop_private.ready_models_installation(identity text primary key,hash text not null);alter table greenloop_private.ready_models_installation enable row level security;revoke all on greenloop_private.ready_models_installation from public,anon,authenticated;
create or replace function public.get_ready_stock_models_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_ready_stock_color_groups_version()='20261112-ready-stock-color-1'and(select count(*)=3 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.ready_models_installation)and not has_function_privilege('authenticated','greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','EXECUTE')and not has_table_privilege('authenticated','greenloop_private.ready_models_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_function_privilege('anon','greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','EXECUTE')and has_function_privilege('authenticated','public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','EXECUTE')and not has_function_privilege('anon','public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','EXECUTE')and exists(select 1 from greenloop_private.capability_rpc_rules where rpc_name='get_ready_stock_models_v1'and rule='{"page":"ready_stock","capability":"view","read":true}'::jsonb)and exists(select 1 from pg_class where oid='greenloop_private.ready_models_installation'::regclass and relrowsecurity)and public.get_page_capabilities_version()='20261016-page-capabilities-1'and exists(select 1 from greenloop_private.office_routines where identity='public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)'and wrapped_hash=md5(pg_get_functiondef(to_regprocedure(identity)))and original_hash=md5(pg_get_functiondef(to_regprocedure(implementation))))then '20261113-ready-stock-models-1'end;$$;
revoke all on function public.get_ready_stock_models_version()from public;grant execute on function public.get_ready_stock_models_version()to anon,authenticated;
insert into greenloop_private.ready_models_installation select sig,md5(pg_get_functiondef(sig::regprocedure))from unnest(array['greenloop_private.rsm_read(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','public.get_ready_stock_models_v1(text,date,jsonb,date,date,text,text,jsonb,integer,integer,text)','public.get_ready_stock_models_version()'])sig on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_ready_stock_models_version()is distinct from '20261113-ready-stock-models-1'then raise exception 'Ready Stock models verification failed. Nothing installed.';end if;end;$$;
notify pgrst,'reload schema';
$ddl$;END;$ready_models_install$;
select public.get_ready_stock_models_version()as installed_ready_stock_models_version;
